"""信用卡客户下月违约概率预测流水线（model_family = logistic_regression）。"""

from typing import Any, Dict, List

import numpy as np
import pandas as pd

from sklearn.compose import ColumnTransformer
from sklearn.impute import SimpleImputer
from sklearn.linear_model import LogisticRegression
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder, StandardScaler

from imblearn.over_sampling import RandomOverSampler, SMOTE
from imblearn.pipeline import Pipeline as ImbalancedPipeline
from imblearn.under_sampling import RandomUnderSampler


# 特征列（与方案一致，不含 ID、标签列或敏感字段）
FEATURE_COLUMNS: List[str] = ["LIMIT_BAL", "PAY_0", "BILL_AMT1"]


def _resolve_columns(config: Dict[str, Any]):
    """解析特征列 / 数值列 / 类别列。"""
    raw_features = config.get("feature_columns") or FEATURE_COLUMNS
    features = [c for c in raw_features if isinstance(c, str)]
    if not features:
        features = list(FEATURE_COLUMNS)

    categorical = [
        c for c in (config.get("categorical_columns") or []) if c in features
    ]
    numeric = [
        c
        for c in (config.get("numeric_columns") or features)
        if c in features and c not in categorical
    ]
    if not numeric and not categorical:
        numeric = list(features)
    return features, numeric, categorical


def _make_encoder():
    """兼容不同 sklearn 版本的 OneHotEncoder 构造。"""
    try:
        return OneHotEncoder(handle_unknown="ignore", sparse_output=False)
    except TypeError:  # sklearn < 1.2
        return OneHotEncoder(handle_unknown="ignore", sparse=False)


def _build_numeric_pipeline():
    steps = [("imputer", SimpleImputer(strategy="median"))]
    steps.append(("scaler", StandardScaler()))
    return Pipeline(steps)


def _build_categorical_pipeline():
    return Pipeline(
        [
            ("imputer", SimpleImputer(strategy="most_frequent")),
            ("encoder", _make_encoder()),
        ]
    )


def _build_preprocessor(numeric_columns: List[str], categorical_columns: List[str]):
    transformers = []
    if numeric_columns:
        transformers.append(("num", _build_numeric_pipeline(), numeric_columns))
    if categorical_columns:
        transformers.append(
            ("cat", _build_categorical_pipeline(), categorical_columns)
        )
    return ColumnTransformer(
        transformers=transformers,
        remainder="drop",
        sparse_threshold=0.0,
    )


def _build_sampler(config: Dict[str, Any]):
    """按配置构造采样器；未要求采样时返回 None（避免改变默认分布）。"""
    name = str(
        config.get("sampling")
        or config.get("imbalance_strategy")
        or config.get("sampler")
        or "none"
    ).lower()
    random_state = config.get("random_state", 42)

    if name in {"random_under", "under", "undersample", "randomundersampler"}:
        return RandomUnderSampler(random_state=random_state)
    if name in {"random_over", "over", "oversample", "randomoversampler"}:
        return RandomOverSampler(random_state=random_state)
    if name in {"smote", "smote_nc"}:
        return SMOTE(random_state=random_state)
    return None


def _build_classifier(config: Dict[str, Any]) -> LogisticRegression:
    class_weight = config.get("class_weight", "balanced")
    if isinstance(class_weight, str) and class_weight.lower() in {"none", "null"}:
        class_weight = None

    return LogisticRegression(
        C=float(config.get("C", 1.0)),
        penalty=str(config.get("penalty", "l2")),
        solver=str(config.get("solver", "lbfgs")),
        max_iter=int(config.get("max_iter", 1000)),
        tol=float(config.get("tol", 1e-4)),
        class_weight=class_weight,
        random_state=int(config.get("random_state", 42)),
        n_jobs=None,
    )


def build_pipeline(config: Dict[str, Any] = None) -> Pipeline:
    """构建包含缺失值处理、缩放、编码、采样与逻辑回归的完整流水线。"""
    config = dict(config or {})

    features, numeric_columns, categorical_columns = _resolve_columns(config)

    preprocessor = _build_preprocessor(numeric_columns, categorical_columns)
    classifier = _build_classifier(config)
    sampler = _build_sampler(config)

    if sampler is None:
        steps = [
            ("preprocessor", preprocessor),
            ("classifier", classifier),
        ]
        return Pipeline(steps=steps)

    # 采样步骤只能出现在 imblearn 流水线中，且仅在 fit 阶段生效
    steps = [
        ("preprocessor", preprocessor),
        ("sampler", sampler),
        ("classifier", classifier),
    ]
    return ImbalancedPipeline(steps=steps)
